\set ON_ERROR_STOP on

create schema if not exists auth;
create schema if not exists private;

do $roles$
begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
end;
$roles$;

do $auth_uid$
begin
  if to_regprocedure('auth.uid()') is null then
    execute $create_fn$
      create function auth.uid()
      returns uuid language sql stable
      as $fn$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $fn$
    $create_fn$;
  end if;
end;
$auth_uid$;

create or replace function private.is_org_store_member(uuid, uuid)
returns boolean language sql stable
as $function$
  select coalesce(nullif(current_setting('test.is_org_store_member', true), '')::boolean, true)
$function$;

create or replace function private.has_org_permission(uuid, text)
returns boolean language sql stable
as $function$
  select coalesce(nullif(current_setting('test.has_org_permission', true), '')::boolean, true)
$function$;

create table public.customers (
  id bigint generated by default as identity primary key,
  organization_id uuid not null
);

create table public.products (
  id bigint generated by default as identity primary key,
  organization_id uuid not null,
  name text not null,
  price numeric not null check (price >= 0)
);

create table public.store_products (
  store_id uuid not null,
  product_id bigint not null references public.products(id),
  quantity integer not null check (quantity >= 0),
  average_cost numeric,
  cost_known boolean not null default true,
  updated_at timestamptz not null default now(),
  primary key (store_id, product_id)
);

create table public.sales (
  id bigint generated by default as identity primary key,
  invoice_number text not null unique,
  customer_id bigint,
  subtotal numeric not null,
  discount numeric not null,
  tax numeric not null,
  total numeric not null,
  payment_status text not null,
  status text not null,
  notes text,
  organization_id uuid not null,
  store_id uuid not null
);

create table public.sale_items (
  id bigint generated by default as identity primary key,
  sale_id bigint not null references public.sales(id),
  product_id bigint not null references public.products(id),
  product_name text not null,
  unit_price numeric not null,
  quantity integer not null,
  discount numeric not null,
  total numeric not null,
  unit_cost numeric,
  cost_total numeric
);

create table public.inventory_movements (
  id bigint generated by default as identity primary key,
  product_id bigint not null references public.products(id),
  movement_type text not null,
  quantity_change integer not null,
  reference_type text not null,
  reference_id bigint not null,
  notes text,
  organization_id uuid not null,
  store_id uuid not null
);

create table public.payments (
  id bigint generated by default as identity primary key,
  sale_id bigint not null references public.sales(id),
  amount numeric not null,
  payment_method text not null,
  reference text,
  paid_at timestamptz not null default now()
);

create table public.audit_logs (
  id bigint generated by default as identity primary key,
  organization_id uuid not null,
  store_id uuid not null,
  action text not null,
  entity_type text not null,
  entity_id text not null,
  metadata jsonb not null
);

create or replace function private.write_audit_log(
  p_organization_id uuid,
  p_store_id uuid,
  p_action text,
  p_entity_type text,
  p_entity_id text,
  p_metadata jsonb
)
returns bigint
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_id bigint;
begin
  insert into public.audit_logs (
    organization_id, store_id, action, entity_type, entity_id, metadata
  ) values (
    p_organization_id, p_store_id, p_action, p_entity_type, p_entity_id, p_metadata
  ) returning id into v_id;
  return v_id;
end;
$function$;
